CREATE TABLE IF NOT EXISTS projects (id UUID PRIMARY KEY, slug VARCHAR(255) UNIQUE NOT NULL, name VARCHAR(255) NOT NULL, tagline TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', status VARCHAR(50) NOT NULL DEFAULT 'building', health VARCHAR(50) NOT NULL DEFAULT 'healthy', owner VARCHAR(255) NOT NULL DEFAULT 'forgeos', stack JSONB NOT NULL DEFAULT '[]'::jsonb, benchmark BOOLEAN DEFAULT false, preview_route VARCHAR(255), preview_status VARCHAR(50), preview_last_built_at TIMESTAMPTZ, created_at TIMESTAMPTZ DEFAULT now() NOT NULL, updated_at TIMESTAMPTZ DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS project_context_entries (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, kind VARCHAR(50) NOT NULL, title VARCHAR(255) NOT NULL, content TEXT NOT NULL, source VARCHAR(100) NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS project_brain_versions (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, version INTEGER NOT NULL, vision TEXT NOT NULL DEFAULT '', requirements JSONB NOT NULL DEFAULT '[]'::jsonb, decisions JSONB NOT NULL DEFAULT '[]'::jsonb, architecture JSONB NOT NULL DEFAULT '[]'::jsonb, "schema" JSONB NOT NULL DEFAULT '[]'::jsonb, integrations JSONB NOT NULL DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS pipeline_stages (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, stage_id VARCHAR(50) NOT NULL, label VARCHAR(100) NOT NULL, status VARCHAR(50) NOT NULL, summary TEXT NOT NULL DEFAULT '', progress INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS source_snapshots (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, commit_sha VARCHAR(255), message TEXT, created_at TIMESTAMPTZ DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS source_files (id UUID PRIMARY KEY, snapshot_id UUID NOT NULL REFERENCES source_snapshots(id) ON DELETE CASCADE, path TEXT NOT NULL, kind VARCHAR(50) NOT NULL DEFAULT 'file', language VARCHAR(50), loc INTEGER, status VARCHAR(50), content TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS ai_runs (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, prompt TEXT NOT NULL, provider VARCHAR(100) NOT NULL, model VARCHAR(100) NOT NULL, status VARCHAR(50) NOT NULL DEFAULT 'draft', tokens_in INTEGER NOT NULL DEFAULT 0, tokens_out INTEGER NOT NULL DEFAULT 0, started_at TIMESTAMPTZ DEFAULT now() NOT NULL, completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS ai_run_steps (id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES ai_runs(id) ON DELETE CASCADE, title VARCHAR(255) NOT NULL, detail TEXT NOT NULL, stage VARCHAR(50) NOT NULL, risk VARCHAR(50) NOT NULL, status VARCHAR(50) NOT NULL, order_idx INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ai_events (id UUID PRIMARY KEY, run_id UUID NOT NULL REFERENCES ai_runs(id) ON DELETE CASCADE, level VARCHAR(50) NOT NULL, stage VARCHAR(50) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS approvals (id UUID PRIMARY KEY, step_id UUID NOT NULL REFERENCES ai_run_steps(id) ON DELETE CASCADE, decision VARCHAR(50) NOT NULL, actor VARCHAR(255) NOT NULL, created_at TIMESTAMPTZ DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS test_runs (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, snapshot_id UUID REFERENCES source_snapshots(id), status VARCHAR(50) NOT NULL, created_at TIMESTAMPTZ DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS test_results (id UUID PRIMARY KEY, test_run_id UUID NOT NULL REFERENCES test_runs(id) ON DELETE CASCADE, name VARCHAR(255) NOT NULL, suite VARCHAR(50) NOT NULL, status VARCHAR(50) NOT NULL, duration_ms INTEGER NOT NULL DEFAULT 0, detail TEXT);
CREATE TABLE IF NOT EXISTS deployments (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, env VARCHAR(50) NOT NULL, status VARCHAR(50) NOT NULL, commit_sha VARCHAR(255), url VARCHAR(255) NOT NULL DEFAULT '', adapter VARCHAR(100) NOT NULL, created_at TIMESTAMPTZ DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events (id UUID PRIMARY KEY, project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, actor VARCHAR(50) NOT NULL, actor_name VARCHAR(255) NOT NULL, action VARCHAR(255) NOT NULL, target VARCHAR(255) NOT NULL, risk VARCHAR(50) NOT NULL, approved BOOLEAN, diff_summary TEXT, stage VARCHAR(50), created_at TIMESTAMPTZ DEFAULT now() NOT NULL);